window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ca0c69fce582f732"]={"versions": [{"id": "FIG-ca0c69fce582f732", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Flussdiagramm zur Darstellung der AUTOSAR-Methodik für die ECU-Konfiguration im Gesamtkontext von AUTOSAR Classic Platform. Das Diagramm modelliert einen sequenziellen Transformations- und Konfigurationsprozess von der Gesamtsystemebene bis zum ausführbaren ECU-Binärimage anhand von Verarbeitungsstufen und Dateiartefakten (.XML und .exe).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Verarbeitungsstufen (Chevron-Aktivitätssymbole):\n<ul class=\"fig-list\"><li>„Configure System“: Entgegennahme der Systemspezifikation und Erstellung der Systemkonfigurationsbeschreibung.\n</li><li>„Extract ECU-Specific Information“: Extraktion der steuergerätespezifischen Anteile aus der Gesamtkonfiguration.\n</li><li>„Configure ECU“: Spezifische Konfiguration von BSW und RTE für das Zielsteuergerät.\n</li><li>„Generate“: Codegenerierung, Kompilierung und Linken zur Erzeugung des Zielabbilds.\n</li></ul>\n</li><li>Daten- und Dateiartefakte (Dokumentensymbole):\n<ul class=\"fig-list\"><li>„System Configuration Input : System“ (.XML): Ursprüngliche Systemeingabedaten (Topologie, Softwarekomponenten, Signale).\n</li><li>„System Configuration Description :System“ (.XML): Vollständige Systemkonfigurationsbeschreibung.\n</li><li>„ECU Extract of System Configuration :System“ (.XML): Extrahierter, steuergerätespezifischer Konfigurationsanteil (ECU Extract).\n</li><li>„ECU“ (.XML): Vollständig konfigurierte ECU-Konfigurationsbeschreibung (BSW/RTE-Parameter).\n</li><li>„ECU“ (.exe): Ausführbares Binary/Image für das Ziel-Steuergerät.\n</li></ul>\n</li><li>Schnittstellen/Kanten: Gerichtete Pfeile verbinden lineare Stufenfolge vom Eingangsdokument über Prozessschritte zu Zwischendokumenten und zum Zielartefakt. Keine expliziten Kardinalitäten angegeben.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Streng sequenzieller linearer Prozessablauf von links nach rechts:</p>\n<ol class=\"fig-list\"><li>„System Configuration Input : System“ (.XML) wird in den Prozessschritt „Configure System“ übergeben.\n</li><li>„Configure System“ erzeugt die „System Configuration Description :System“ (.XML).\n</li><li>„Extract ECU-Specific Information“ liest die Systemkonfiguration und erzeugt den „ECU Extract of System Configuration :System“ (.XML).\n</li><li>„Configure ECU“ verarbeitet den ECU-Extract und führt zur vollständigen ECU-Konfigurationsbeschreibung „ECU“ (.XML).\n</li><li>„Generate“ generiert und baut aus der ECU-Konfiguration die ausführbare Binärdatei „ECU“ (.exe).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gibt den normativen Leitfaden für den AUTOSAR-Methodikablauf im Kontext der Spezifikation TPS ECU Configuration vor. Definiert die grundlegende Datenflusskette für AUTOSAR-Werkzeugketten (System Authoring Tool, ECU Extract Creator, ECU Configuration Tool, RTE/BSW Code Generators &amp; Build Toolchain). Betont die formale Rolle des ECU Extract als bindende Schnittstelle zwischen Fahrzeughersteller (OEM) und Tier-1-Zulieferer.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-84d6ff09366dae1b", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methodik-Übersichtsdiagramm nach SPEM/AUTOSAR-Methodology-Standard. Zeigt das Beziehungsgeflecht zwischen Entwicklungsaktivitäten (Tasks) und Arbeitsergebnissen (Work Products / Artefakte) über die Entwicklungsdomänen System, Softwarekomponenten (SWC), Basissoftware (BSW) und ECU-Integration hinweg. Formaler Übergang von einer sequenziellen Datenflussdarstellung zu einem netzwerkartigen Aktivitäts- und Artefakt-Modell mit expliziten Kardinalitäten und Stereotypen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Aktivitäten (gelbe Boxen mit SPEM-Tasksymbol / Rolle-und-Dokument):\n<ul class=\"fig-list\"><li>„Develop System“: Erstellung der Gesamtsystem- und Netzwerkarchitektur.\n</li><li>„Develop Sub-System“: Verfeinerung und Detaillierung von Teilsystemen.\n</li><li>„Develop Application Software“: Entwicklung und Beschreibung atomarer Softwarekomponenten.\n</li><li>„Develop Basic Software“: Entwicklung und Parametrierung der BSW-Module.\n</li><li>„Integrate Software for ECU“: Integration aller Softwareteile, RTE-Erzeugung und ECU-Softwareerstellung.\n</li></ul>\n</li><li>Artefakte (orange Briefumschlagsymbole mit Portleiste links):\n<ul class=\"fig-list\"><li>„BSW Standard Package“ (Kardinalität am Ausgang: 1).\n</li><li>„Standard Package“ (oben rechts, Kardinalität am Ausgang: 1..*).\n</li><li>„System Constraint Description“ (Kardinalität 0..1).\n</li><li>„Abstract System Description“ (Kardinalität 1..* bzw. 0..*).\n</li><li>„Overall VFB System“ (Kardinalität 1).\n</li><li>„System Extract“ (Kardinalität 0..*).\n</li><li>„Delivered Atomic Software Components“ (Kardinalität 1..*).\n</li><li>„BSW Module Delivered Bundle“ (Kardinalität 1..*).\n</li><li>„ECU Extract“ (Kardinalitäten: von „Develop System“ 1..<em>, von „Develop Sub-System“ 1..</em>, Eingang in Integration 1).\n</li><li>„ECU Software“ (Kardinalität 1).\n</li></ul>\n</li><li>Beziehungen und Schnittstellen:\n<ul class=\"fig-list\"><li>Gerichtete Kanten mit Stereotypen «input» und «output».\n</li><li>Kardinalitätsangaben (z. B. <code>0..1</code>, <code>1</code>, <code>1..*</code>, <code>0..*</code>) spezifizieren Pflicht- und Wahleingaben bzw. Multiplizitäten für Generierungsstufen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Parallel-iterativer und hierarchischer Methodenablauf:</p>\n<ol class=\"fig-list\"><li>Vorlaufende System- und VFB-Definitionen speisen „Develop System“ über „Standard Package“ (1..<em>), „System Constraint Description“ (0..1) und „Abstract System Description“ (0..</em>).\n</li><li>„Develop System“ liefert:\n<ul class=\"fig-list\"><li>„Abstract System Description“ (1..*) rückgekoppelt oder vorwärtsgerichtet,\n</li><li>„System Extract“ (0..*), das an „Develop Sub-System“ übergeben wird,\n</li><li>direkt erzeugten „ECU Extract“ (1..*).\n</li></ul>\n</li><li>„Develop Sub-System“ verarbeitet den „System Extract“ (1) und liefert ebenfalls „ECU Extract“ (1..*).\n</li><li>Parallele Stränge:\n<ul class=\"fig-list\"><li>SWC-Pfad: „Standard Package“ (1..<em>) und „Overall VFB System“ (1) gehen in „Develop Application Software“ ein und führen zu „Delivered Atomic Software Components“ (1..</em>).\n</li><li>BSW-Pfad: „BSW Standard Package“ (1) geht in „Develop Basic Software“ ein und erzeugt „BSW Module Delivered Bundle“ (1..*).\n</li></ul>\n</li><li>Konvergenz: In „Integrate Software for ECU“ fließen „BSW Module Delivered Bundle“ (1..<em>), „ECU Extract“ (1) und „Delivered Atomic Software Components“ (1..</em>) als «input» zusammen.\n</li><li>Abschluss: „Integrate Software for ECU“ erzeugt das Endprodukt „ECU Software“ (1, «output»).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Referenz-Methodik für AUTOSAR-konforme Entwicklungsprozesse ab Release 4.1. Definiert die werkzeugübergreifende Interoperabilität und Lieferbeziehungen:</p>\n<ul class=\"fig-list\"><li>Entkopplung von System- und Teilsystemebene über standardisierte Extrakte („System Extract“, „ECU Extract“).\n</li><li>Parallele Entwicklung von Application SWCs und BSW vor der finalen ECU-Software-Integration.\n</li><li>Multiplizitäten regeln die Zulässigkeit optionaler Artefakte (z. B. Constraints) sowie 1..*-Zulieferungen (mehrere SWCs und BSW-Module pro ECU).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-3c74ef52844862c8", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methodik-Übersichtsdiagramm nach SPEM/AUTOSAR-Methodology-Standard. Zeigt das Beziehungsgeflecht zwischen Entwicklungsaktivitäten (Tasks) und Arbeitsergebnissen (Work Products / Artefakte) über die Entwicklungsdomänen System, Softwarekomponenten (SWC), Basissoftware (BSW) und ECU-Integration hinweg. Formaler Übergang von einer sequenziellen Datenflussdarstellung zu einem netzwerkartigen Aktivitäts- und Artefakt-Modell mit expliziten Kardinalitäten und Stereotypen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Aktivitäten:\n<ul class=\"fig-list\"><li>„Develop System“\n</li><li>„Develop Sub-System“\n</li><li>„Develop Application Software“\n</li><li>„Develop Basic Software“\n</li><li>„Integrate Software for ECU“\n</li></ul>\n</li><li>Artefakte:\n<ul class=\"fig-list\"><li>„BSW Standard Package“ (1)\n</li><li>„Standard Package“ (1..*)\n</li><li>„System Constraint Description“ (0..1)\n</li><li>„Abstract System Description“ (1..* bzw. 0..*)\n</li><li>„Overall VFB System“ (1)\n</li><li>„Transformer Design Bundle“: Neues Artefakt für Serialisierungs- und Transformationskonfigurationen (Kardinalität <code>0..*</code> am Ausgang von „Develop System“, <code>0..*</code> als «input» in „Develop Basic Software“).\n</li><li>„System Extract“ (0..*)\n</li><li>„Delivered Atomic Software Components“ (1..*)\n</li><li>„BSW Module Delivered Bundle“ (1..*)\n</li><li>„ECU Extract“ (1..* / 1)\n</li><li>„ECU Software“ (1)\n</li></ul>\n</li><li>Kanten und Stereotypen:\n<ul class=\"fig-list\"><li>«output» von „Develop System“ zu „Transformer Design Bundle“ (<code>0..*</code>).\n</li><li>«input» von „Transformer Design Bundle“ (<code>0..*</code>) zu „Develop Basic Software“.\n</li><li>Übrige Beziehungen identisch mit «input»/«output»-Annotationen und Kardinalitäten.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablauf wie im Basis-Methodikmodell, erweitert um die Transformer-Kette:</p>\n<ol class=\"fig-list\"><li>Bei der Gesamtsystementwicklung („Develop System“) können neben dem System Extract und ECU Extract optional Transformer-Design-Beschreibungen („Transformer Design Bundle“, Kardinalität <code>0..*</code>) generiert werden.\n</li><li>Das „Transformer Design Bundle“ wird von der Basissoftwareentwicklung („Develop Basic Software“) als Eingabe übernommen (<code>0..* «input»</code>), um transformerspezifische BSW-Module und Schnittstellen (z. B. SOME/IP Transformer, E2E Transformer) passend zur Systemkonfiguration zu konfigurieren und zu implementieren.\n</li><li>Die nachgelagerte Integration in „Integrate Software for ECU“ verarbeitet die resultierenden BSW-Module gemeinsam mit dem ECU Extract und den Atomic SWCs zur „ECU Software“.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Integriert das AUTOSAR-Transformer-Konzept (TPS Transformer) normativ in die Gesamtmethodik. Das „Transformer Design Bundle“ regelt den Datenaustausch und die Protokoll-Transformation (z. B. Serialisierung, Safety/Security-Wrapper) zwischen Systementwurf und BSW-Implementierung. Entwickler von Basissoftware müssen Transformer-Spezifikationen direkt aus dem Systemmodell als standardisierten Input verarbeiten können.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-fc475f741a63db49", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methodik-Übersichtsdiagramm der AUTOSAR-Entwicklungsmethodik, strukturiert über fünf explizite funktionale Partitionen (Swimlanes):</p>\n<ul class=\"fig-list\"><li>„Basic Software“ (BSW)\n</li><li>„System“\n</li><li>„Virtual Functional Bus“ (VFB)\n</li><li>„Software Component“ (SWC)\n</li><li>„ECU“ (Integrationsebene)\n</li></ul>\n<p class=\"fig-p\">Das Diagramm verortet Aktivitäten und Artefakte klar in den jeweiligen Domänen und modelliert deren bereichsübergreifende Kopplungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Partitionen und enthaltene Elemente:\n<ul class=\"fig-list\"><li>Partition „Basic Software“:\n<ul class=\"fig-list\"><li>Artefakt: „BSW Standard Package“ (1)\n</li><li>Aktivität: „Develop Basic Software“\n</li><li>Artefakt: „BSW Module Delivered Bundle“ (1..*)\n</li></ul>\n</li><li>Partition „System“:\n<ul class=\"fig-list\"><li>Aktivität: „Develop an Abstract System Description“\n</li><li>Aktivität: „Develop System“\n</li><li>Aktivität: „Develop Sub-System“\n</li><li>Artefakte: „System Constraint Description“ (0..1), „Abstract System Description“ (1..* / 0..<em>), „Transformer Design Bundle“ (0..</em>), „System Extract“ (0..<em>), „ECU Extract“ (1..</em>)\n</li></ul>\n</li><li>Partition „Virtual Functional Bus“:\n<ul class=\"fig-list\"><li>Artefakt: „VFB AUTOSAR Standard Package“ (1..*)\n</li><li>Aktivität: „Develop a VFB System Description“\n</li><li>Artefakt: „Overall VFB System“ (1)\n</li></ul>\n</li><li>Partition „Software Component“:\n<ul class=\"fig-list\"><li>Aktivität: „Develop Application Software“\n</li><li>Artefakt: „Delivered Atomic Software Components“ (1..*)\n</li></ul>\n</li><li>Partition „ECU“:\n<ul class=\"fig-list\"><li>Aktivität: „Integrate Software for ECU“\n</li><li>Artefakt: „ECU Software Delivered“ (1)\n</li></ul>\n</li></ul>\n</li><li>Schnittstellen und Stereotypen: Sämtliche Flüsse sind mit «input» bzw. «output» sowie Kardinalitäten (0..1, 1, 0..<em>, 1..</em>) annotiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Strukturierter Ablauf über Domänengrenzen hinweg:</p>\n<ol class=\"fig-list\"><li>VFB- und System-Initialisierung:\n<ul class=\"fig-list\"><li>Aus „VFB AUTOSAR Standard Package“ (1..*) speisen sich „Develop an Abstract System Description“ und „Develop a VFB System Description“.\n</li><li>„Develop an Abstract System Description“ erzeugt „Abstract System Description“ (1..*).\n</li><li>„Develop a VFB System Description“ erzeugt „Overall VFB System“ (1).\n</li></ul>\n</li><li>System- und Sub-System-Entwicklung:\n<ul class=\"fig-list\"><li>„Develop System“ konsumiert „System Constraint Description“ (0..1), „Abstract System Description“ (0..*) und „Overall VFB System“ (0..1).\n</li><li>„Develop System“ erzeugt „Transformer Design Bundle“ (0..<em>), „System Extract“ (0..</em>) sowie direkt „ECU Extract“ (1..*).\n</li><li>„Develop Sub-System“ überführt „System Extract“ (1) in „ECU Extract“ (1..*).\n</li></ul>\n</li><li>Domänenspezifische Umsetzung:\n<ul class=\"fig-list\"><li>In „Basic Software“: „Develop Basic Software“ verarbeitet „BSW Standard Package“ (1) und „Transformer Design Bundle“ (0..<em>) zu „BSW Module Delivered Bundle“ (1..</em>).\n</li><li>In „Software Component“: „Develop Application Software“ verarbeitet „Overall VFB System“ (1) zu „Delivered Atomic Software Components“ (1..*).\n</li></ul>\n</li><li>ECU-Ebene: „Integrate Software for ECU“ aggregiert „BSW Module Delivered Bundle“ (1..<em>), „ECU Extract“ (1) und „Delivered Atomic Software Components“ (1..</em>) und erzeugt als finales Lieferartefakt „ECU Software Delivered“ (1).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gibt die verbindliche Zuordnung von Prozessschritten zu organisatorischen und technischen Rollen vor (OEM, Systemintegrator, BSW-Zulieferer, SWC-Entwickler, ECU-Integrator). Benennung von „ECU Software Delivered“ präzisiert den formalen Liefercharakter des Endprodukts der ECU-Integration. Die Partitionierung erzwingt eine klare Trennung zwischen hardwareunabhängiger VFB-/SWC-Modellierung, Systemvernetzung und hardwarenaher BSW-/ECU-Konfiguration.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-fb977ec3ba368c67", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methodik-Übersichtsdiagramm der AUTOSAR-Entwicklungsmethodik, strukturiert über fünf explizite funktionale Partitionen (Swimlanes):</p>\n<ul class=\"fig-list\"><li>„Basic Software“ (BSW)\n</li><li>„System“\n</li><li>„Virtual Functional Bus“ (VFB)\n</li><li>„Software Component“ (SWC)\n</li><li>„ECU“ (Integrationsebene)\n</li></ul>\n<p class=\"fig-p\">Das Diagramm verortet Aktivitäten und Artefakte klar in den jeweiligen Domänen und modelliert deren bereichsübergreifende Kopplungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Partitionen identisch: „Basic Software“, „System“, „Virtual Functional Bus“, „Software Component“, „ECU“.\n</li><li>Aktivitäten:\n<ul class=\"fig-list\"><li>„Develop an Abstract System Description“\n</li><li>„Develop System“\n</li><li>„Develop Sub- System“ (Schreibweise mit Leerzeichen nach dem Bindestrich)\n</li><li>„Develop a VFB System Description“\n</li><li>„Develop Application Software“\n</li><li>„Develop Basic Software“\n</li><li>„Integrate Software for ECU“\n</li></ul>\n</li><li>Artefakte und Kardinalitäten:\n<ul class=\"fig-list\"><li>„BSW Standard Package“ (1)\n</li><li>„VFB AUTOSAR Standard Package“ (1..*)\n</li><li>„System Constraint Description“ (0..1)\n</li><li>„Abstract System Description“ (1..* / 0..*)\n</li><li>„Overall VFB System“ (1)\n</li><li>„Transformer Design Bundle“ (0..*)\n</li><li>„System Extract“ (0..* / 1)\n</li><li>„Delivered Atomic Software Components“ (1..*)\n</li><li>„BSW Module Delivered Bundle“ (1..*)\n</li><li>„ECU Extract“ (1..* / 1)\n</li><li>„ECU Software Delivered“ (1)\n</li></ul>\n</li><li>Kanten und Annotationen identisch; geringfügig verändertes Text- und Kanten-Layout.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Strukturierter Ablauf über Domänengrenzen hinweg:</p>\n<ol class=\"fig-list\"><li>VFB- und System-Initialisierung:\n<ul class=\"fig-list\"><li>Aus „VFB AUTOSAR Standard Package“ (1..*) speisen sich „Develop an Abstract System Description“ und „Develop a VFB System Description“.\n</li><li>„Develop an Abstract System Description“ erzeugt „Abstract System Description“ (1..*).\n</li><li>„Develop a VFB System Description“ erzeugt „Overall VFB System“ (1).\n</li></ul>\n</li><li>System- und Sub-System-Entwicklung:\n<ul class=\"fig-list\"><li>„Develop System“ konsumiert „System Constraint Description“ (0..1), „Abstract System Description“ (0..*) und „Overall VFB System“ (0..1).\n</li><li>„Develop System“ erzeugt „Transformer Design Bundle“ (0..<em>), „System Extract“ (0..</em>) sowie direkt „ECU Extract“ (1..*).\n</li><li>„Develop Sub-System“ überführt „System Extract“ (1) in „ECU Extract“ (1..*).\n</li></ul>\n</li><li>Domänenspezifische Umsetzung:\n<ul class=\"fig-list\"><li>In „Basic Software“: „Develop Basic Software“ verarbeitet „BSW Standard Package“ (1) und „Transformer Design Bundle“ (0..<em>) zu „BSW Module Delivered Bundle“ (1..</em>).\n</li><li>In „Software Component“: „Develop Application Software“ verarbeitet „Overall VFB System“ (1) zu „Delivered Atomic Software Components“ (1..*).\n</li></ul>\n</li><li>ECU-Ebene: „Integrate Software for ECU“ aggregiert „BSW Module Delivered Bundle“ (1..<em>), „ECU Extract“ (1) und „Delivered Atomic Software Components“ (1..</em>) und erzeugt als finales Lieferartefakt „ECU Software Delivered“ (1).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gibt die verbindliche Zuordnung von Prozessschritten zu organisatorischen und technischen Rollen vor (OEM, Systemintegrator, BSW-Zulieferer, SWC-Entwickler, ECU-Integrator). Benennung von „ECU Software Delivered“ präzisiert den formalen Liefercharakter des Endprodukts der ECU-Integration. Die Partitionierung erzwingt eine klare Trennung zwischen hardwareunabhängiger VFB-/SWC-Modellierung, Systemvernetzung und hardwarenaher BSW-/ECU-Konfiguration.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5bcf776b7bc22d05", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methodik-Übersichtsdiagramm der AUTOSAR-Entwicklungsmethodik, strukturiert über fünf explizite funktionale Partitionen (Swimlanes):</p>\n<ul class=\"fig-list\"><li>„Basic Software“ (BSW)\n</li><li>„System“\n</li><li>„Virtual Functional Bus“ (VFB)\n</li><li>„Software Component“ (SWC)\n</li><li>„ECU“ (Integrationsebene)\n</li></ul>\n<p class=\"fig-p\">Das Diagramm verortet Aktivitäten und Artefakte klar in den jeweiligen Domänen und modelliert deren bereichsübergreifende Kopplungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Partitionen identisch: „Basic Software“, „System“, „Virtual Functional Bus“, „Software Component“, „ECU“.\n</li><li>Aktivitäten:\n<ul class=\"fig-list\"><li>„Develop an Abstract System Description“\n</li><li>„Develop System“\n</li><li>„Develop Sub- System“ (Schreibweise mit Leerzeichen nach dem Bindestrich)\n</li><li>„Develop a VFB System Description“\n</li><li>„Develop Application Software“\n</li><li>„Develop Basic Software“\n</li><li>„Integrate Software for ECU“\n</li></ul>\n</li><li>Artefakte und Kardinalitäten:\n<ul class=\"fig-list\"><li>„BSW Standard Package“ (1)\n</li><li>„VFB AUTOSAR Standard Package“ (1..*)\n</li><li>„System Constraint Description“ (0..1)\n</li><li>„Abstract System Description“ (1..* / 0..*)\n</li><li>„Overall VFB System“ (1)\n</li><li>„Transformer Design Bundle“ (0..*)\n</li><li>„System Extract“ (0..* / 1)\n</li><li>„Delivered Atomic Software Components“ (1..*)\n</li><li>„BSW Module Delivered Bundle“ (1..*)\n</li><li>„ECU Extract“ (1..* / 1)\n</li><li>„ECU Software Delivered“ (1)\n</li></ul>\n</li><li>Kanten und Annotationen identisch; geringfügig verändertes Text- und Kanten-Layout.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Strukturierter Ablauf über Domänengrenzen hinweg:</p>\n<ol class=\"fig-list\"><li>VFB- und System-Initialisierung:\n<ul class=\"fig-list\"><li>Aus „VFB AUTOSAR Standard Package“ (1..*) speisen sich „Develop an Abstract System Description“ und „Develop a VFB System Description“.\n</li><li>„Develop an Abstract System Description“ erzeugt „Abstract System Description“ (1..*).\n</li><li>„Develop a VFB System Description“ erzeugt „Overall VFB System“ (1).\n</li></ul>\n</li><li>System- und Sub-System-Entwicklung:\n<ul class=\"fig-list\"><li>„Develop System“ konsumiert „System Constraint Description“ (0..1), „Abstract System Description“ (0..*) und „Overall VFB System“ (0..1).\n</li><li>„Develop System“ erzeugt „Transformer Design Bundle“ (0..<em>), „System Extract“ (0..</em>) sowie direkt „ECU Extract“ (1..*).\n</li><li>„Develop Sub-System“ überführt „System Extract“ (1) in „ECU Extract“ (1..*).\n</li></ul>\n</li><li>Domänenspezifische Umsetzung:\n<ul class=\"fig-list\"><li>In „Basic Software“: „Develop Basic Software“ verarbeitet „BSW Standard Package“ (1) und „Transformer Design Bundle“ (0..<em>) zu „BSW Module Delivered Bundle“ (1..</em>).\n</li><li>In „Software Component“: „Develop Application Software“ verarbeitet „Overall VFB System“ (1) zu „Delivered Atomic Software Components“ (1..*).\n</li></ul>\n</li><li>ECU-Ebene: „Integrate Software for ECU“ aggregiert „BSW Module Delivered Bundle“ (1..<em>), „ECU Extract“ (1) und „Delivered Atomic Software Components“ (1..</em>) und erzeugt als finales Lieferartefakt „ECU Software Delivered“ (1).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gibt die verbindliche Zuordnung von Prozessschritten zu organisatorischen und technischen Rollen vor (OEM, Systemintegrator, BSW-Zulieferer, SWC-Entwickler, ECU-Integrator). Benennung von „ECU Software Delivered“ präzisiert den formalen Liefercharakter des Endprodukts der ECU-Integration. Die Partitionierung erzwingt eine klare Trennung zwischen hardwareunabhängiger VFB-/SWC-Modellierung, Systemvernetzung und hardwarenaher BSW-/ECU-Konfiguration.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-ca0c69fce582f732", "to": "FIG-84d6ff09366dae1b", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Ersetzung des vereinfachten sequenziellen 4-Stufen-Flussdiagramms durch das vollständige AUTOSAR-Methodikmodell mit differenzierten Aktivitäten und Artefakten nach SPEM/Methodology-Muster.\n</li><li>Einführung der Aktivitäten „Develop System“, „Develop Sub-System“, „Develop Application Software“, „Develop Basic Software“ und „Integrate Software for ECU“.\n</li><li>Differenzierung der Artefakte in „BSW Standard Package“, „Overall VFB System / Standard Package“, „Abstract System Description“, „System Constraint Description“, „System Extract“, „Delivered Atomic Software Components“, „BSW Module Delivered Bundle“, „ECU Extract“ und „ECU Software“.\n</li><li>Definition präziser Kardinalitäten und Stereotypen («input», «output») an sämtlichen Daten- und Artefaktflüssen.\n</li></ul>"}, {"from": "FIG-84d6ff09366dae1b", "to": "FIG-3c74ef52844862c8", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Neues Artefakt „Transformer Design Bundle“ hinzugefügt.\n</li><li>Neuer Datenfluss von der Aktivität „Develop System“ als «output» (Kardinalität <code>0..*</code>) zum Artefakt „Transformer Design Bundle“.\n</li><li>Neuer Datenfluss vom Artefakt „Transformer Design Bundle“ mit Kardinalität <code>0..*</code> als «input» in die Aktivität „Develop Basic Software“.\n</li></ul>"}, {"from": "FIG-3c74ef52844862c8", "to": "FIG-fc475f741a63db49", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Einführung von fünf gestrichelten Partitionen/Swimlanes zur strukturellen Zuordnung: „Basic Software“, „System“, „Virtual Functional Bus“, „Software Component“ und „ECU“.\n</li><li>Explizite Ausdifferenzierung der vorgelagerten Aktivitäten „Develop an Abstract System Description“ und „Develop a VFB System Description“.\n</li><li>Umbenennung des Endartefakts von „ECU Software“ zu „ECU Software Delivered“.\n</li><li>Vereinheitlichung und Präzisierung der Beschriftung der Standard-Pakete zu „BSW Standard Package“ und „VFB AUTOSAR Standard Package“.\n</li><li>Anpassung der Pfeilführungen und Beschriftungsplatzierungen entsprechend der Partitionierung.\n</li></ul>"}, {"from": "FIG-fc475f741a63db49", "to": "FIG-fb977ec3ba368c67", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Trennstrich-Schreibweise der Aktivität „Develop Sub-System“ zu „Develop Sub- System“ geändert (Einfügen eines Leerzeichens nach dem Bindestrich).\n</li><li>Verschiebungen/Korrekturen von Textpositionen und Verbindungspfeil-Andockpunkten (u. a. Beschriftung <code>«input»</code> am Eingang von „Develop System“ und „Develop an Abstract System Description“ leicht versetzt).\n</li></ul>"}, {"from": "FIG-fb977ec3ba368c67", "to": "FIG-5bcf776b7bc22d05", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
